$scope.$watch(() => { return this.breakpoints.isMatched('gt-sm'); }, (isGtSm?: any) => {
    this.isGtSm = isGtSm;
    this.isLockSidenav = isGtSm;
    this.isShowSidenav = isGtSm;
    if (!isGtSm) {
        setTimeout(() => {
            $animate.enabled(this.siteSideNav, true);
        }, 0, false);
    } else {
        $animate.enabled(this.siteSideNav, false);
    }
});
